require_once __DIR__.'/../config/config.php'; admin_required(); $msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check($_POST['csrf']??null);if(!empty($_FILES['csv']['tmp_name'])){$fh=fopen($_FILES['csv']['tmp_name'],'r');$headers=array_map('trim',fgetcsv($fh));$required=['sku','name','category','price','cost','stock'];$missing=array_diff($required,$headers);if($missing)$err='Missing columns: '.implode(', ',$missing);else{ $count=0;$pdo=db();$sql="INSERT INTO products (sku,name,category,description,price,cost,stock,sizes,colors,status,featured,image) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),description=VALUES(description),price=VALUES(price),cost=VALUES(cost),stock=VALUES(stock),sizes=VALUES(sizes),colors=VALUES(colors),status=VALUES(status),featured=VALUES(featured),image=VALUES(image)";$st=$pdo->prepare($sql);while(($row=fgetcsv($fh))!==false){$r=array_combine($headers,$row);$st->execute([$r['sku'],$r['name'],$r['category'],$r['description']??'',(float)$r['price'],(float)$r['cost'],(int)$r['stock'],$r['sizes']??'',$r['colors']??'',$r['status']??'active',(int)($r['featured']??0),$r['image']??'']);$count++;}fclose($fh);$msg="$count rows imported/updated.";}}}
$title='CSV Import';require __DIR__.'/admin_header.php'; ?>
